import java.io.*;
import java.net.*;
import java.util.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.DefaultHandler;
import javax.servlet.*;
import javax.servlet.http.*;

public class DocumentImportServlet extends HttpServlet {

    private static final Set<String> ALLOWED_TAGS = Set.of(
        "document", "metadata", "title", "author", "body", "section", "paragraph");

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("xml")) {
            resp.sendError(400, "Content-Type must be application/xml");
            return;
        }

        String xmlData = new String(req.getInputStream().readAllBytes(), "UTF-8");

        // Basic size check
        if (xmlData.length() > 1048576) {
            resp.sendError(413, "Document too large");
            return;
        }

        // Reject obvious script injection in text content
        if (xmlData.toLowerCase().contains("<script")) {
            resp.sendError(400, "Invalid content detected");
            return;
        }

        try {
            SAXParserFactory factory = SAXParserFactory.newInstance();
            // Note: we intentionally allow DTDs for legacy document format support
            // The factory does NOT disable external entities
            SAXParser parser = factory.newSAXParser();

            DocumentContentHandler handler = new DocumentContentHandler();
            parser.parse(new InputSource(new StringReader(xmlData)), handler);

            String title = handler.getTitle();
            String author = handler.getAuthor();
            String bodyText = handler.getBodyText();

            // Store parsed document
            req.getServletContext().setAttribute(
                "doc_" + System.currentTimeMillis(), 
                Map.of("title", title, "author", author, "body", bodyText));

            resp.setContentType("application/json");
            resp.getWriter().write(
                "{\"status\":\"imported\",\"title\":\"" + escapeJson(title) + "\"}");

        } catch (ParserConfigurationException | SAXException e) {
            resp.sendError(400, "XML parsing error: " + e.getMessage());
        }
    }

    private String escapeJson(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }

    static class DocumentContentHandler extends DefaultHandler {
        private StringBuilder currentText = new StringBuilder();
        private String title = "";
        private String author = "";
        private StringBuilder bodyText = new StringBuilder();
        private String currentElement = "";

        @Override
        public void startElement(String uri, String localName, String qName, Attributes attrs) {
            currentElement = qName.toLowerCase();
            currentText.setLength(0);
        }

        @Override
        public void characters(char[] ch, int start, int length) {
            currentText.append(ch, start, length);
        }

        @Override
        public void endElement(String uri, String localName, String qName) {
            switch (currentElement) {
                case "title": title = currentText.toString().trim(); break;
                case "author": author = currentText.toString().trim(); break;
                case "paragraph": bodyText.append(currentText.toString().trim()).append("\n"); break;
            }
            currentText.setLength(0);
        }

        // Note: no resolveEntity override — uses default resolution

        public String getTitle() { return title; }
        public String getAuthor() { return author; }
        public String getBodyText() { return bodyText.toString(); }
    }
}
